mapper.select:
        SELECT


--         级联表的字段

        FROM sys_dict_item  a



                and a.id in

                #{item}



                and a.dict_code  = #{params.dictCode}


                and a.dict_name like CONCAT('%',#{params.dictName},'%')


                  and a.item_code >= #{params.codeIndexStart}   


                  and a.item_code <= #{params.codeIndexEnd}   


                and a.item_code = #{params.itemCode}


                and a.item_name like CONCAT('%',#{params.itemName},'%')


                and (
                    a.parent_id = #{params.parentId}
                )


                and a.remark like CONCAT('%',#{params.remark},'%')




        order by a.${params.orderBy} desc
